// Save the project settings from a host message, including a logo upload. The upload is validated here
// (type by content, size, name generated by us); `setProject` then re-validates the stored file with `resolveLogo`.
import { constants } from "node:fs";
import { lstat, open, readFile, unlink } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join, resolve } from "node:path";
import { setProject, resolveLogo, type ProjectInput, type ProjectOptions } from "./config.ts";
import { LOGO_TYPES, MAX_LOGO_BASE64, MAX_LOGO_BYTES, extOf, type LogoUpload, type ProjectFields } from "./project-rules.ts";

const SIGS: Record<string, (b: Buffer) => boolean> = {
  png: (b) => b.length > 8 && b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])),
  jpg: (b) => b.length > 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff,
  gif: (b) => b.length > 6 && /^GIF8[79]a$/.test(b.subarray(0, 6).toString("latin1")),
  webp: (b) => b.length > 12 && b.subarray(0, 4).toString("latin1") === "RIFF" && b.subarray(8, 12).toString("latin1") === "WEBP",
  svg: (b) => {
    const t = b.toString("utf8").replace(/^﻿/, "").trimStart();
    return (t.startsWith("<svg") || t.startsWith("<?xml")) && /<svg[\s>]/.test(t) && !/<script|<foreignObject|\son[a-z]+\s*=/i.test(t);
  },
};

/** Canonical extension of an upload whose content matches its claimed type, or throws. */
export function checkLogoUpload(up: LogoUpload): { bytes: Buffer; ext: string } {
  if (typeof up?.name !== "string" || typeof up.data !== "string") throw new Error("bad logo upload");
  const claimed = extOf(up.name);
  const ext = claimed === "jpeg" ? "jpg" : claimed;
  if (!Object.hasOwn(LOGO_TYPES, claimed)) throw new Error("logo must be a png, jpg, webp, gif or svg file");
  if (up.data.length > MAX_LOGO_BASE64 || up.data.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(up.data)) throw new Error(`logo must be at most ${MAX_LOGO_BYTES / 1024} KiB`);
  const bytes = Buffer.from(up.data, "base64");
  if (bytes.length === 0) throw new Error("logo file is empty");
  if (bytes.length > MAX_LOGO_BYTES) throw new Error(`logo is larger than ${MAX_LOGO_BYTES / 1024} KiB`);
  if (!SIGS[ext](bytes)) throw new Error(`the file is not a valid ${ext} image`);
  return { bytes, ext };
}

/** Copy the upload into `dir` under a generated name (`logo-<hash>.<ext>`); returns the name and whether the file is new. */
async function storeLogo(dir: string, bytes: Buffer, ext: string): Promise<{ name: string; created: boolean }> {
  const name = `logo-${createHash("sha256").update(bytes).digest("hex").slice(0, 12)}.${ext}`;
  const file = resolve(dir, name);
  try {
    // O_EXCL | O_NOFOLLOW: never overwrite, never write through a symlink planted at the generated name.
    const fh = await open(file, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o644);
    try {
      await fh.writeFile(bytes);
    } finally {
      await fh.close();
    }
    return { name, created: true };
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code !== "EEXIST") throw e;
  }
  const st = await lstat(file);
  if (!st.isFile() || st.isSymbolicLink()) throw new Error("logo name is taken by something that is not a file");
  if (!(await readFile(file)).equals(bytes)) throw new Error("logo name is taken by a different file");
  return { name, created: false };
}

/**
 * Apply a validated `setProject` message: store the uploaded logo (if any), update the config and commit
 * `gitask.json` plus that one logo file by pathspec. If saving fails, a logo file created by this call is removed again.
 */
export async function saveProject(dir: string, fields: ProjectFields, opts: ProjectOptions = {}): Promise<{ committed: boolean }> {
  const { logo, ...rest } = fields;
  const input: ProjectInput = { ...rest };
  if (logo === undefined) return setProject(dir, input, opts);
  if (logo === null) {
    input.logo = null;
    return setProject(dir, input, opts);
  }
  const { bytes, ext } = checkLogoUpload(logo);
  const stored = await storeLogo(dir, bytes, ext);
  try {
    await resolveLogo(dir, stored.name);
    input.logo = stored.name;
    return await setProject(dir, input, { ...opts, withFile: join(resolve(dir), stored.name) });
  } catch (e) {
    if (stored.created) await unlink(join(resolve(dir), stored.name)).catch(() => undefined);
    throw e;
  }
}
